<div class="tree-item" v-if="isAtomic"><template v-if="(typeof types[&quot;allowedValues&quot;] !== &quot;undefined&quot;)"><div class="tree-value">{{resolveUnit(value, types)}}</div></template><template v-else><div class="tee-value">{{value}}</div></template></div><div class="tree-list" v-else-if="isList"><div class="tree-list-item" v-for="subval of value"><TreeDisplay :value="subval" :types="types"></TreeDisplay></div></div><div class="tree-list" v-else-if="isObj"><template v-if="(typeof value[&quot;value&quot;] !== &quot;undefined&quot;) &amp;&amp; (typeof value[&quot;units&quot;] !== &quot;undefined&quot;)"><div class="tree-value">{{value["value"]}} {{resolveUnit(value["units"], types["Units"])}}</div></template><template v-else><div class="tree-list-item" v-for="[subfield, subval] of Object.entries(value)"><template v-if="nonEmpty(subval)"><div class="tree-label">{{prepFieldName(subfield)}}</div><TreeDisplay :value="subval" :types="resolveType(types, subfield)"></TreeDisplay></template></div></template></div>